#!/usr/bin/env node
/**
 * generate-segment-mapping.mjs
 *
 * Build-time script: scans blog content files and auto-generates
 * BLOG_SEGMENT_LABELS mapping (slug → Chinese title) for the admin dashboard.
 *
 * Data source: apps/blog/content/en/*.mdx frontmatter → slug
 *              apps/blog/content/zh/{slug}.mdx frontmatter → Chinese title
 *
 * Run: node packages/scripts/generate-segment-mapping.mjs
 * Output: apps/admin/src/lib/segment-mapping.ts (auto-generated, do not edit manually)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..', '..');
const BLOG_EN_DIR = path.join(ROOT, 'apps/blog/content/en');
const BLOG_ZH_DIR = path.join(ROOT, 'apps/blog/content/zh');
const OUTPUT_FILE = path.join(ROOT, 'apps/admin/src/lib/segment-mapping.ts');

/**
 * Parse frontmatter from an MDX file.
 * Returns the frontmatter fields as a map, or null if file doesn't exist / can't be parsed.
 */
function parseFrontmatter(filePath) {
  if (!fs.existsSync(filePath)) return null;
  const content = fs.readFileSync(filePath, 'utf-8');
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const fields = {};
  for (const line of match[1].split('\n')) {
    const keyMatch = line.match(/^(\w+):\s+"(.*)"$/);
    if (keyMatch) {
      fields[keyMatch[1]] = keyMatch[2];
    }
  }
  return fields;
}

/**
 * Clean colons and em-dashes from a title (consistent with R08 rule).
 */
function cleanTitle(title) {
  return title
    .replace(/\s*[:：]\s*/g, ' ')     // Replace colons (full/half-width) with space
    .replace(/\s*—\s*/g, ' ')          // Em-dash
    .replace(/\s*[-–]\s*/g, ' ')       // En-dash / hyphen
    .replace(/\s+/g, ' ')              // Collapse whitespace
    .trim();
}

// ── Build mapping ──

const enFiles = fs.readdirSync(BLOG_EN_DIR).filter(f => f.endsWith('.mdx'));
const entries = [];

for (const file of enFiles.sort()) {
  const slug = file.replace(/\.mdx$/, '');
  const enPath = path.join(BLOG_EN_DIR, file);
  const zhPath = path.join(BLOG_ZH_DIR, file);

  const enFm = parseFrontmatter(enPath);
  const zhFm = parseFrontmatter(zhPath);

  if (!enFm || !enFm.title) {
    console.warn(`  ⚠  Skipping ${slug}: no English frontmatter title`);
    continue;
  }

  const enTitle = cleanTitle(enFm.title);
  const zhTitle = zhFm ? cleanTitle(zhFm.title) : enTitle; // fallback to English if no zh

  entries.push({ slug, enTitle, zhTitle });
}

// ── Generate TypeScript file ──

const lines = [
  '// AUTO-GENERATED — do not edit manually',
  `// Generated by packages/scripts/generate-segment-mapping.mjs at ${new Date().toISOString().slice(0, 10)}`,
  `// Source: ${entries.length} blog articles from apps/blog/content/en/ + apps/blog/content/zh/`,
  '',
  '/**',
  ' * Blog article slug → Chinese display name mapping.',
  ' * Used by the dashboard pathToBreadcrumb() to display Chinese path labels',
  ' * without requiring manual SEGMENT_LABELS entries.',
  ' */',
  'export const BLOG_SEGMENT_LABELS: Record<string, string> = {',
];

for (const { slug, zhTitle } of entries) {
  const escaped = zhTitle.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  lines.push(`  '${slug}': \`${escaped}\`,`);
}

lines.push('};');
lines.push('');
lines.push('/**');
lines.push(' * Blog article slug → English display name mapping (for English locale).');
lines.push(' */');
lines.push('export const BLOG_SEGMENT_LABELS_EN: Record<string, string> = {');

for (const { slug, enTitle } of entries) {
  const escaped = enTitle.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  lines.push(`  '${slug}': \`${escaped}\`,`);
}

lines.push('};');

const output = lines.join('\n') + '\n';

// ── Write output ──

fs.mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
fs.writeFileSync(OUTPUT_FILE, output, 'utf-8');

console.log(`\n✅ Generated ${OUTPUT_FILE}`);
console.log(`   ${entries.length} blog article mappings (slug → Chinese title)`);
